package com.yonlab.vision;
import android.content.Context;import android.graphics.*;import android.os.SystemClock;import org.json.*;import java.util.*;

/** Pose inference plus interpretable 2D exercise geometry. No medical or invented repetition score. */
final class FitnessCoach {
 static void run(Context c,String id,Bitmap input,OneModelRunner.Cancel cancel,OneModelRunner.Result r)throws Exception{
  if(!Arrays.asList("coach-mlkit","coach-mlkit-accurate","coach-movenet-lightning","coach-movenet-thunder","coach-posenet","coach-blazepose").contains(id))throw new IllegalArgumentException("coach model");long load=SystemClock.elapsedRealtime();boolean movenet=id.startsWith("coach-movenet"),plus=PlusPoseEngine.supports(id);OnePoseEngine ml=movenet||plus?null:new OnePoseEngine("coach-mlkit-accurate".equals(id));OneMoveNetEngine move=movenet?new OneMoveNetEngine(c,id):null;PlusPoseEngine added=plus?new PlusPoseEngine(c,id):null;AutoCloseable engine=plus?added:movenet?move:ml;if(plus)r.modelSha256=added.sha256;else if(movenet)r.modelSha256=move.sha256;r.engineCreated=true;r.loadMs=SystemClock.elapsedRealtime()-load;
  try{long infer=SystemClock.elapsedRealtime();List<PoseGeometry.Point> points=plus?added.pose(input):movenet?move.pose(input):ml.pose(input);ExpansionImageRunner.check(cancel);List<PoseGeometry.Point> visible=PoseGeometry.visible(points);Map<String,Double> angles=CoachGeometry.analyze(points,input.getWidth(),input.getHeight());r.image=input.copy(Bitmap.Config.ARGB_8888,true);Canvas canvas=new Canvas(r.image);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(0xff0068f8);p.setStrokeWidth(Math.max(3,input.getWidth()/180f));for(PoseGeometry.Point[] e:PoseGeometry.edges(points))canvas.drawLine(e[0].x*input.getWidth(),e[0].y*input.getHeight(),e[1].x*input.getWidth(),e[1].y*input.getHeight(),p);p.setColor(0xff13a381);for(PoseGeometry.Point x:visible)canvas.drawCircle(x.x*input.getWidth(),x.y*input.getHeight(),Math.max(4,input.getWidth()/100f),p);
   JSONArray landmarks=new JSONArray();for(PoseGeometry.Point x:points)landmarks.put(new JSONObject().put("id",x.id).put("x",x.x).put("y",x.y).put("likelihood",x.likelihood));JSONObject measures=new JSONObject();for(Map.Entry<String,Double> e:angles.entrySet())measures.put(e.getKey(),e.getValue());r.metrics.put("landmarks",points.size()).put("visibleLandmarks",visible.size()).put("points",landmarks).put("anglesDegrees",measures).put("observation",CoachGeometry.observation(angles)).put("geometryScope","2D observed joints in original image pixel aspect; absent joints are omitted").put("sourceWidth",input.getWidth()).put("sourceHeight",input.getHeight()).put("pipeline",(plus?(id.equals("coach-blazepose")?"BlazePose detector + full33 landmark":"PoseNet MobileNet COCO17"):movenet?"MoveNet COCO17":"ML Kit33")+" → visible-joint gate → pixel-aspect-aware angles and alignment");
   r.summary=CoachGeometry.observation(angles)+" · 지점 "+visible.size()+"개";StringBuilder text=new StringBuilder();String[][] labels={{"leftElbow","왼쪽 팔꿈치"},{"rightElbow","오른쪽 팔꿈치"},{"leftKnee","왼쪽 무릎"},{"rightKnee","오른쪽 무릎"},{"leftHip","왼쪽 고관절"},{"rightHip","오른쪽 고관절"},{"shoulderTilt","어깨 기울기"},{"trunkLean","상체 기울기"}};for(String[] pair:labels)if(angles.containsKey(pair[0]))text.append(pair[1]).append("  ").append(String.format(Locale.ROOT,"%.1f°",angles.get(pair[0]))).append('\n');if(angles.containsKey("leftKnee")&&angles.containsKey("rightKnee"))text.append("좌우 무릎 각도 차이  ").append(String.format(Locale.ROOT,"%.1f°",Math.abs(angles.get("leftKnee")-angles.get("rightKnee"))));r.detail=text.toString();r.inferenceMs=SystemClock.elapsedRealtime()-infer;
  }finally{engine.close();r.engineCloseReturned=true;}
 }
}
